{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Human PET imaging of [11C]CURB, which shares the piperidine-ethoxy-aryl and fused heteroaromatic motif, showed rapid and high brain uptake, supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "JNJ-5207852, containing two basic piperidine groups and an aryl-oxy-propyl linker, crossed the BBB and accumulated to high brain concentrations in rodents, demonstrating that dicationic basic amines can still achieve CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A structurally related H3 inverse agonist PET tracer with a piperidine-ethyl side chain and coumarin-like core was not a P-gp substrate and showed rapid brain uptake in monkeys, arguing against the efflux prior being decisive.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Compound 8a, with a pyrrolidine-propoxy-aryl motif, achieved a rat brain/plasma ratio of 2.6, directly showing good brain exposure for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "An N-methyl analogue with a pyrrolidine-ethoxy-aryl motif and amide/biphenyl substituents showed a poor brain-to-blood ratio in rats, providing a contradictory example within the broader series.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Roxatidine, a smaller piperidine-containing molecule, showed only trace CSF exposure in humans, indicating that not all related basic ethers achieve meaningful CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: multiple structurally related aryl-O-alkyl-basic-amine compounds show direct brain uptake, PET exposure, or brain/plasma ratios above 0.7 despite basic amines; the two negative examples are less transferable due to amide/polar features or smaller size. The physicochemical prior of low passive permeability is outweighed by convergent in vivo CNS-penetration evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query molecule.",
    "Morgan similarities are low (0.27-0.34), limiting exact structural transfer.",
    "Query has higher molecular weight and two ionizable amines compared with most supportive analogues.",
    "Efflux liability of the query was not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

